describe('Multi-step form navigation with data persistence', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/multi-step-form');
    cy.get('[data-testid="form-container"]').should('be.visible');
  });

  it('should navigate back to previous step and retain entered data', () => {
    // Step 1: Fill in personal information
    cy.get('[data-testid="step-1"]').should('be.visible');
    cy.get('[data-testid="input-firstName"]').type('John');
    cy.get('[data-testid="input-lastName"]').type('Doe');
    cy.get('[data-testid="input-email"]').type('john.doe@example.com');

    // Verify step 1 data is visible
    cy.get('[data-testid="input-firstName"]').should('have.value', 'John');
    cy.get('[data-testid="input-lastName"]').should('have.value', 'Doe');
    cy.get('[data-testid="input-email"]').should('have.value', 'john.doe@example.com');

    // Navigate to step 2
    cy.get('[data-testid="button-next"]').click();
    cy.get('[data-testid="step-2"]').should('be.visible');

    // Step 2: Fill in address information
    cy.get('[data-testid="input-street"]').type('123 Main Street');
    cy.get('[data-testid="input-city"]').type('New York');
    cy.get('[data-testid="input-zipCode"]').type('10001');

    // Navigate to step 3
    cy.get('[data-testid="button-next"]').click();
    cy.get('[data-testid="step-3"]').should('be.visible');

    // Step 3: Fill in preferences
    cy.get('[data-testid="checkbox-newsletter"]').check();
    cy.get('[data-testid="select-frequency"]').select('weekly');

    // Navigate back to step 2
    cy.get('[data-testid="button-back"]').click();
    cy.get('[data-testid="step-2"]').should('be.visible');

    // Verify step 2 data is retained
    cy.get('[data-testid="input-street"]').should('have.value', '123 Main Street');
    cy.get('[data-testid="input-city"]').should('have.value', 'New York');
    cy.get('[data-testid="input-zipCode"]').should('have.value', '10001');

    // Navigate back to step 1
    cy.get('[data-testid="button-back"]').click();
    cy.get('[data-testid="step-1"]').should('be.visible');

    // Verify step 1 data is retained
    cy.get('[data-testid="input-firstName"]').should('have.value', 'John');
    cy.get('[data-testid="input-lastName"]').should('have.value', 'Doe');
    cy.get('[data-testid="input-email"]').should('have.value', 'john.doe@example.com');
  });

