    // Fill step 1
    cy.get('[data-testid="input-firstName"]').type('Jane');
    cy.get('[data-testid="input-lastName"]').type('Smith');
    cy.get('[data-testid="input-email"]').type('jane.smith@example.com');
    cy.get('[data-testid="button-next"]').click();

    // Fill step 2
    cy.get('[data-testid="input-street"]').type('456 Oak Avenue');
    cy.get('[data-testid="input-city"]').type('Los Angeles');
    cy.get('[data-testid="input-zipCode"]').type('90001');
    cy.get('[data-testid="button-next"]').click();

    // Go back to step 2
    cy.get('[data-testid="button-back"]').click();
    cy.get('[data-testid="step-2"]').should('be.visible');
    cy.get('[data-testid="input-street"]').should('have.value', '456 Oak Avenue');

    // Go forward to step 3
    cy.get('[data-testid="button-next"]').click();
    cy.get('[data-testid="step-3"]').should('be.visible');

    // Fill step 3
    cy.get('[data-testid="checkbox-newsletter"]').check();
    cy.get('[data-testid="select-frequency"]').select('monthly');

    // Go back to step 2 again
    cy.get('[data-testid="button-back"]').click();
    cy.get('[data-testid="input-city"]').should('have.value', 'Los Angeles');

    // Go back to step 1
    cy.get('[data-testid="button-back"]').click();
    cy.get('[data-testid="input-firstName"]').should('have.value', 'Jane');

    // Go forward through all steps
    cy.get('[data-testid="button-next"]').click();
    cy.get('[data-testid="button-next"]').click();
    cy.get('[data-testid="step-3"]').should('be.visible');
    cy.get('[data-testid="checkbox-newsletter"]').should('be.checked');
    cy.get('[data-testid="select-frequency"]').should('have.value', 'monthly');
  });

