    cy.get('[data-testid="input-firstName"]').type('Robert');
    cy.get('[data-testid="input-lastName"]').type('Johnson');
    cy.get('[data-testid="input-email"]').type('robert@example.com');
    cy.get('[data-testid="button-next"]').click();

    // Fill step 2
    cy.get('[data-testid="input-street"]').type('789 Pine Road');
    cy.get('[data-testid="input-city"]').type('Chicago');
    cy.get('[data-testid="button-next"]').click();

    // Click reset button
    cy.get('[data-testid="button-reset"]').click();
    cy.get('[data-testid="modal-confirm"]').should('be.visible');
    cy.get('[data-testid="button-confirm-reset"]').click();

    // Verify form is reset to step 1
    cy.get('[data-testid="step-1"]').should('be.visible');
    cy.get('[data-testid="input-firstName"]').should('have.value', '');
    cy.get('[data-testid="input-lastName"]').should('have.value', '');
    cy.get('[data-testid="input-email"]').should('have.value', '');
  });

